<?php
declare(strict_types=1);
require_once __DIR__.'/PosAccess.php';
require_once __DIR__.'/CheckoutLinks.php';
final class RideCash
{
    public function __construct(private PDO $db){}
    private function query(string $sql,array $args=[]):PDOStatement{$q=$this->db->prepare($sql);$q->execute($args);return $q;}
    private static function code(mixed $v):string{if(!is_string($v)||!preg_match('/^JM-X[A-F0-9]{12}$/D',$v))throw new HttpError(400,'Mã đơn xe không hợp lệ.');return $v;}
    private static function permit(array $actor):void{if(($actor['role']??'')!=='ADMIN'&&(($actor['role']??'')!=='STAFF'||!in_array('COLLECT',$actor['permissions']??[],true)))throw new HttpError(403,'Chưa được cấp quyền thu tiền.');}
    private static function uid():string{$h=bin2hex(random_bytes(16));return substr($h,0,8).'-'.substr($h,8,4).'-4'.substr($h,13,3).'-'.dechex(8+hexdec($h[16])%4).substr($h,17,3).'-'.substr($h,20);}
    public function status(array $in,array $actor):array
    {
        self::permit($actor);if(count($in)!==1||array_diff(array_keys($in),['code']))throw new HttpError(400,'Yêu cầu tra cứu không hợp lệ.');$code=self::code($in['code']??null);$r=$this->query('SELECT status,data FROM jingo_ride_bookings WHERE code=?',[$code])->fetch(PDO::FETCH_ASSOC);if(!$r)throw new HttpError(404,'Không tìm thấy đơn xe.');$d=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);$out=['paymentStatus'=>$d['paymentStatus']??'UNPAID','status'=>$r['status'],'total'=>$d['total'],'from'=>$d['fromName'],'to'=>$d['toName']];$receipt=$d['cashReceipt']??null;if($receipt&&(($actor['role']??'')==='ADMIN'||in_array($receipt['counterId'],$actor['counterIds'],true)))$out['cashReceipt']=$receipt;return $out;
    }
    public function collect(array $in,array $actor):array
    {
        self::permit($actor);if(count($in)!==3||array_diff(array_keys($in),['code','counterId','expectedTotal'])||!is_string($in['counterId']??null)||!preg_match('/^[a-zA-Z0-9_-]{1,80}$/D',$in['counterId'])||!is_int($in['expectedTotal']??null)||$in['expectedTotal']<1||$in['expectedTotal']>15000000000)throw new HttpError(400,'Kiểm tra mã xe, quầy và số tiền.');$code=self::code($in['code']??null);$staff=$actor['role']==='STAFF';if($staff&&!in_array($in['counterId'],$actor['counterIds'],true))throw new HttpError(404,'Không tìm thấy quầy được cấp quyền.');
        $this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{
            if(!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');$counter=$this->query('SELECT data FROM jingo_counters WHERE id=? FOR UPDATE',[$in['counterId']])->fetchColumn();if($counter===false)throw new HttpError(404,'Quầy không hoạt động.');if($staff)PosAccess::live($this->db,$actor['id'],$in['counterId'],'COLLECT');$counter=json_decode($counter,true,512,JSON_THROW_ON_ERROR);if($counter['status']!=='ACTIVE')throw new HttpError(404,'Quầy không hoạt động.');$r=$this->query('SELECT id,code,status,data,visit_date FROM jingo_ride_bookings WHERE code=? FOR UPDATE',[$code])->fetch(PDO::FETCH_ASSOC);if(!$r)throw new HttpError(404,'Không tìm thấy đơn xe.');CheckoutLinks::guard($this->db,'rideId',$r['id']);if($r['status']==='CANCELLED')throw new HttpError(409,'Đơn xe đã hủy.');$d=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);$prior=$d['cashReceipt']??null;if($prior&&$prior['counterId']===$in['counterId']&&$prior['amount']===$in['expectedTotal']){$this->db->commit();return $prior;}if(($d['paymentStatus']??'UNPAID')==='PAID')throw new HttpError(409,'Đơn xe đã thanh toán.');if(in_array($r['status'],['PENDING','WAITING_MATCH'],true))throw new HttpError(409,'Xác nhận chuyến hoặc chốt nhóm trước khi thu tiền.');if(!in_array($r['status'],['MATCHED','WAITING_PICKUP','PICKED_UP','RUNNING','COMPLETED'],true))throw new HttpError(409,'Trạng thái đơn xe không cho phép thu tiền.');if($d['total']!==$in['expectedTotal'])throw new HttpError(409,'Giá đã thay đổi. Tra cứu lại đơn xe.');
            // Future/imported QR attempts must block cash while still active.
            if($this->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='jingo_ride_payment_attempts'")->fetchColumn()&&$this->query("SELECT id FROM jingo_ride_payment_attempts WHERE ride_id=? AND status='PENDING' AND expires_at>UTC_TIMESTAMP() LIMIT 1",[$r['id']])->fetchColumn())throw new HttpError(409,'Đơn đang có QR còn hiệu lực. Kiểm tra thanh toán hoặc chờ QR hết hạn trước khi thu tiền mặt.');
            $shiftId=$this->query('SELECT shift_id FROM jingo_pos_open_shifts WHERE counter_id=?',[$in['counterId']])->fetchColumn();if(!$shiftId)throw new HttpError(409,'Mở ca quầy trước khi thu tiền mặt.');$shift=$this->query('SELECT closed_at,counter_id FROM jingo_pos_shifts WHERE id=? FOR UPDATE',[$shiftId])->fetch(PDO::FETCH_ASSOC);if(!$shift||$shift['closed_at']!==null||$shift['counter_id']!==$in['counterId'])throw new HttpError(409,'Ca quầy không còn mở.');if((int)$this->query('SELECT COUNT(*) FROM jingo_pos_cash_movements WHERE shift_id=?',[$shiftId])->fetchColumn()>=10000)throw new HttpError(409,'Ca đã đạt 10.000 khoản thu chi. Chốt ca và mở ca mới.');$actorId=$staff?'pos-user:'.$actor['id']:$actor['id'];$id=self::uid();$receipt=['id'=>$id,'code'=>$code,'amount'=>$in['expectedTotal'],'paidAt'=>gmdate('Y-m-d\TH:i:s\Z'),'counterId'=>$in['counterId'],'counterName'=>$counter['name'],'shiftId'=>$shiftId,'actorName'=>$actor['name']??$actor['email'],'from'=>$d['fromName'],'to'=>$d['toName'],'date'=>$r['visit_date'],'time'=>$d['time']];$json=json_encode($receipt,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);$this->query("INSERT INTO jingo_pos_cash_movements(id,shift_id,kind,amount,reference,note,actor_id,actor_name,request_hash) VALUES (?,?,'IN',?,?,'Thu tiền mặt đơn xe',?,?,?)",[$id,$shiftId,$receipt['amount'],$code,$actorId,$receipt['actorName'],hash('sha256',$json)]);$this->query('UPDATE jingo_pos_shifts SET version=version+1 WHERE id=?',[$shiftId]);$d=array_replace($d,['paymentStatus'=>'PAID','paidAmount'=>$receipt['amount'],'paidAt'=>$receipt['paidAt'],'paymentReference'=>$id,'cashReceipt'=>$receipt]);$this->query('UPDATE jingo_ride_bookings SET data=?,version=version+1 WHERE id=?',[json_encode($d,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$r['id']]);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actorId,'ride.cash.collect',$r['id']]);$this->db->commit();return $receipt;
        }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}
    }
    public function receipt(string $code,array $actor):array{$r=$this->status(['code'=>$code],$actor);if(!isset($r['cashReceipt']))throw new HttpError(404,'Không tìm thấy biên nhận được cấp quyền.');return $r['cashReceipt'];}
}
